INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c1w02', 'lesson', 'c1w02', 0, '{"id":"c1w02","course":1,"week":"02","title":"Paesi e nazionalità","subtitle":"Countries & nationalities","topics":["essere","adjective agreement","numbers 0–20"],"italian":"Sono britannico, ma vivo a Londra.","english":"I’m British, but I live in London.","prompt":"Complete: Maria è italian__.","answer":"italiana","canDo":"I can say where I am from and describe nationality.","canDoIt":"So dire da dove vengo e descrivere la nazionalità.","summaryIt":"Presentati con paese, città e nazionalità; fai concordare gli aggettivi e usa i numeri da 0 a 20.","summaryEn":"In this lesson: I can say where I am from and describe nationality.","grammarRuleIds":["essere","agreement"],"remember":[{"it":"Ricorda: sono, sei, è, siamo, siete, sono.","en":"Use essere for identity, origin, qualities and location."},{"it":"Controlla l’ultima lettera di nome e aggettivo.","en":"The adjective agrees with the noun in gender and number."}],"writeDown":[{"it":"Frase modello: Sono britannico, ma vivo a Londra.","en":"Model sentence: I’m British, but I live in London."},{"it":"Regola chiave: Uso essere per identità, origine, qualità e posizione.","en":"Key rule: Use essere for identity, origin, qualities and location."},{"it":"Obiettivo personale: So dire da dove vengo e descrivere la nazionalità.","en":"Personal goal: I can say where I am from and describe nationality."}],"mistakes":[{"wrong":"Io è inglese.","right":"Io sono inglese.","noteIt":"La nazionalità concorda: italiano/italiana.","noteEn":"Nationality agrees in gender."},{"wrong":"due case grande","right":"due case grandi","noteIt":"Gli aggettivi in -e hanno il plurale in -i.","noteEn":"Adjectives ending in -e form the plural in -i."}],"sourceRefs":["Archivio PDF · Paesi e nazionalità","CELI A1 · competenze richieste","CILS A1 · descrittori"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c1w03', 'lesson', 'c1w03', 1, '{"id":"c1w03","course":1,"week":"03","title":"Informazioni personali","subtitle":"Personal information","topics":["avere","stare","numbers 20–100"],"italian":"Ho ventidue anni e sto molto bene.","english":"I’m twenty-two years old and I’m very well.","prompt":"Translate: I am 25 years old.","answer":"Ho venticinque anni.","canDo":"I can exchange age, health and contact details.","canDoIt":"So scambiare età, stato di salute e recapiti.","summaryIt":"Scambia età, indirizzo e telefono usando avere, stare e i numeri fino a 100.","summaryEn":"In this lesson: I can exchange age, health and contact details.","grammarRuleIds":["avere","irregular","forms"],"remember":[{"it":"Memorizza: ho, hai, ha, abbiamo, avete, hanno.","en":"Use avere for age, possession and many physical states."},{"it":"Crea una frase personale per ogni forma difficile.","en":"Learn common irregular verbs as complete patterns."},{"it":"Controlla due volte numeri e grafia.","en":"Recognise standard fields for personal details."}],"writeDown":[{"it":"Frase modello: Ho ventidue anni e sto molto bene.","en":"Model sentence: I’m twenty-two years old and I’m very well."},{"it":"Regola chiave: Uso avere per età, possesso e molte sensazioni.","en":"Key rule: Use avere for age, possession and many physical states."},{"it":"Obiettivo personale: So scambiare età, stato di salute e recapiti.","en":"Personal goal: I can exchange age, health and contact details."}],"mistakes":[{"wrong":"Sono venticinque anni.","right":"Ho venticinque anni.","noteIt":"In italiano l’età si ‘ha’.","noteEn":"In Italian you ‘have’ an age."},{"wrong":"Ando al cinema.","right":"Vado al cinema.","noteIt":"Non applicare automaticamente le forme regolari.","noteEn":"Do not automatically apply regular endings."}],"sourceRefs":["Archivio PDF · Informazioni personali","CELI A1 · competenze richieste","CILS A1 · descrittori"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c1w04', 'lesson', 'c1w04', 2, '{"id":"c1w04","course":1,"week":"04","title":"Lavoro e professioni","subtitle":"Jobs & professions","topics":["articles","fare","question words"],"italian":"Faccio l’ingegnere in un’azienda internazionale.","english":"I work as an engineer in an international company.","prompt":"Choose: ___ psicologo (un / uno).","answer":"uno psicologo","canDo":"I can ask and answer simple questions about work.","canDoIt":"So fare e rispondere a domande semplici sul lavoro.","summaryIt":"Parla di professioni, scegli gli articoli e formula domande formali e informali.","summaryEn":"In this lesson: I can ask and answer simple questions about work.","grammarRuleIds":["articles","questions","irregular"],"remember":[{"it":"Prima ascolta il suono, poi scegli l’articolo.","en":"The article depends on gender, number and initial sound."},{"it":"Abbina ogni domanda all’informazione cercata.","en":"Use question words to request specific details."},{"it":"Crea una frase personale per ogni forma difficile.","en":"Learn common irregular verbs as complete patterns."}],"writeDown":[{"it":"Frase modello: Faccio l’ingegnere in un’azienda internazionale.","en":"Model sentence: I work as an engineer in an international company."},{"it":"Regola chiave: L’articolo dipende da genere, numero e suono iniziale.","en":"Key rule: The article depends on gender, number and initial sound."},{"it":"Obiettivo personale: So fare e rispondere a domande semplici sul lavoro.","en":"Personal goal: I can ask and answer simple questions about work."}],"mistakes":[{"wrong":"il studente","right":"lo studente","noteIt":"Usa lo/gli prima di s+consonante, z, ps, gn, x e y; l’ prima di vocale.","noteEn":"Use lo/gli before special consonant clusters; l’ before a vowel."},{"wrong":"Come ti chiama?","right":"Come si chiama?","noteIt":"Con Lei uso la terza persona: Come si chiama?","noteEn":"Formal Lei takes third-person singular."}],"sourceRefs":["Archivio PDF · Lavoro e professioni","CELI A1 · competenze richieste","CILS A1 · descrittori"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c1w05', 'lesson', 'c1w05', 3, '{"id":"c1w05","course":1,"week":"05","title":"Al bar e al ristorante","subtitle":"At the bar & restaurant","topics":["ordering","polite requests","food"],"italian":"Vorrei un caffè e un cornetto, per favore.","english":"I’d like a coffee and a croissant, please.","prompt":"How do you ask for the bill?","answer":"Il conto, per favore.","canDo":"I can order and pay in a café or restaurant.","canDoIt":"So ordinare e pagare al bar o al ristorante.","summaryIt":"Ordina con cortesia, leggi un menù e descrivi cibi e preferenze.","summaryEn":"In this lesson: I can order and pay in a café or restaurant.","grammarRuleIds":["ordering","articles","buono-bene"],"remember":[{"it":"Aggiungi per favore e chiudi con grazie.","en":"Order with vorrei, prendo, per me and posso avere."},{"it":"Prima ascolta il suono, poi scegli l’articolo.","en":"The article depends on gender, number and initial sound."},{"it":"Chiediti: cosa oppure come?","en":"Buono describes a noun; bene describes an action."}],"writeDown":[{"it":"Frase modello: Vorrei un caffè e un cornetto, per favore.","en":"Model sentence: I’d like a coffee and a croissant, please."},{"it":"Regola chiave: Per ordinare uso vorrei, prendo, per me e posso avere.","en":"Key rule: Order with vorrei, prendo, per me and posso avere."},{"it":"Obiettivo personale: So ordinare e pagare al bar o al ristorante.","en":"Personal goal: I can order and pay in a café or restaurant."}],"mistakes":[{"wrong":"Voglio un’acqua!","right":"Vorrei un’acqua, per favore.","noteIt":"Vorrei è più cortese di voglio.","noteEn":"Vorrei is more polite than voglio."},{"wrong":"il studente","right":"lo studente","noteIt":"Usa lo/gli prima di s+consonante, z, ps, gn, x e y; l’ prima di vocale.","noteEn":"Use lo/gli before special consonant clusters; l’ before a vowel."}],"sourceRefs":["Archivio PDF · Al bar e al ristorante","CELI A1 · competenze richieste","CILS A1 · descrittori"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c1w06', 'lesson', 'c1w06', 4, '{"id":"c1w06","course":1,"week":"06","title":"Il tempo libero","subtitle":"Free time","topics":["present tense","frequency","hobbies"],"italian":"Nel tempo libero leggo e vado spesso al cinema.","english":"In my free time I read and often go to the cinema.","prompt":"Put in order: spesso / nuoto / io.","answer":"Io nuoto spesso.","canDo":"I can describe hobbies and how often I do them.","canDoIt":"So descrivere i miei hobby e la loro frequenza.","summaryIt":"Descrivi hobby e settimana con presente, giorni e frequenza.","summaryEn":"In this lesson: I can describe hobbies and how often I do them.","grammarRuleIds":["present","irregular","frequency"],"remember":[{"it":"Segna sempre la famiglia del verbo.","en":"Remove -are, -ere or -ire and add the subject ending."},{"it":"Crea una frase personale per ogni forma difficile.","en":"Learn common irregular verbs as complete patterns."},{"it":"Ordina gli avverbi da sempre a mai.","en":"Use frequency adverbs close to the verb."}],"writeDown":[{"it":"Frase modello: Nel tempo libero leggo e vado spesso al cinema.","en":"Model sentence: In my free time I read and often go to the cinema."},{"it":"Regola chiave: Tolgo -are, -ere o -ire e aggiungo la desinenza del soggetto.","en":"Key rule: Remove -are, -ere or -ire and add the subject ending."},{"it":"Obiettivo personale: So descrivere i miei hobby e la loro frequenza.","en":"Personal goal: I can describe hobbies and how often I do them."}],"mistakes":[{"wrong":"Io lavorare a Londra.","right":"Io lavoro a Londra.","noteIt":"Alcuni -ire aggiungono -isc-: preferisco.","noteEn":"Some -ire verbs add -isc-."},{"wrong":"Ando al cinema.","right":"Vado al cinema.","noteIt":"Non applicare automaticamente le forme regolari.","noteEn":"Do not automatically apply regular endings."}],"sourceRefs":["Archivio PDF · Il tempo libero","CELI A1 · competenze richieste","CILS A1 · descrittori"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c1w07', 'lesson', 'c1w07', 5, '{"id":"c1w07","course":1,"week":"07","title":"Piacere e l’ora","subtitle":"Likes & telling the time","topics":["piacere","agreement","time"],"italian":"Mi piace cucinare, ma non mi piacciono i dolci.","english":"I like cooking, but I don’t like sweets.","prompt":"Choose: Mi piace / piacciono le città italiane.","answer":"Mi piacciono le città italiane.","canDo":"I can express likes and tell the time.","canDoIt":"So esprimere preferenze e dire l’ora.","summaryIt":"Esprimi gusti con piace/piacciono e comunica l’ora.","summaryEn":"In this lesson: I can express likes and tell the time.","grammarRuleIds":["piacere","time"],"remember":[{"it":"Guarda la cosa dopo il verbo.","en":"The liked thing controls the verb."},{"it":"Distingui Che ore sono? da A che ora...?","en":"Say è l’una but sono le due, le tre, and so on."}],"writeDown":[{"it":"Frase modello: Mi piace cucinare, ma non mi piacciono i dolci.","en":"Model sentence: I like cooking, but I don’t like sweets."},{"it":"Regola chiave: La cosa gradita controlla il verbo: piace con singolare/infinito, piacciono con plurale.","en":"Key rule: The liked thing controls the verb."},{"it":"Obiettivo personale: So esprimere preferenze e dire l’ora.","en":"Personal goal: I can express likes and tell the time."}],"mistakes":[{"wrong":"Mi piace le città.","right":"Mi piacciono le città.","noteIt":"La persona è mi, ti, gli, le, ci, vi o gli.","noteEn":"Represent the person with an indirect pronoun."},{"wrong":"È le nove.","right":"Sono le nove.","noteIt":"Per orari: all’una, alle otto.","noteEn":"For scheduled times: all’una, alle otto."}],"sourceRefs":["Archivio PDF · Piacere e l’ora","CELI A1 · competenze richieste","CILS A1 · descrittori"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c1w08', 'lesson', 'c1w08', 6, '{"id":"c1w08","course":1,"week":"08","title":"In albergo","subtitle":"Hotel & prepositions","topics":["prepositions","c’è / ci sono","potere"],"italian":"C’è una camera libera al secondo piano?","english":"Is there a free room on the second floor?","prompt":"Combine: in + la camera.","answer":"nella camera","canDo":"I can book a simple hotel room and describe facilities.","canDoIt":"So prenotare una camera semplice e descrivere i servizi.","summaryIt":"Prenota una camera, descrivi servizi e combina le preposizioni.","summaryEn":"In this lesson: I can book a simple hotel room and describe facilities.","grammarRuleIds":["prepositions","articulated-preps","ce-ci-sono","modals"],"remember":[{"it":"Impara la preposizione dentro una frase.","en":"Simple prepositions express different relationships."},{"it":"Scomponi: a + lo = allo; in + la = nella.","en":"Di, a, da, in and su combine with the article."},{"it":"Conta il nome prima di scegliere.","en":"Use c’è for one thing and ci sono for more than one."}],"writeDown":[{"it":"Frase modello: C’è una camera libera al secondo piano?","en":"Model sentence: Is there a free room on the second floor?"},{"it":"Regola chiave: Di, a, da, in, con, su, per e tra/fra esprimono relazioni diverse.","en":"Key rule: Simple prepositions express different relationships."},{"it":"Obiettivo personale: So prenotare una camera semplice e descrivere i servizi.","en":"Personal goal: I can book a simple hotel room and describe facilities."}],"mistakes":[{"wrong":"Vivo a Italia.","right":"Vivo in Italia.","noteIt":"Con città uso spesso a; con paesi uso spesso in.","noteEn":"Often use a with cities and in with countries."},{"wrong":"Vado al stadio.","right":"Vado allo stadio.","noteIt":"Trova prima l’articolo del nome.","noteEn":"Find the noun’s article first."}],"sourceRefs":["Archivio PDF · In albergo","CELI A1 · competenze richieste","CILS A1 · descrittori"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c1w09', 'lesson', 'c1w09', 7, '{"id":"c1w09","course":1,"week":"09","title":"Primo ripasso","subtitle":"First revision","topics":["articles","verbs","professions"],"italian":"La cuoca lavora in cucina e prepara piatti deliziosi.","english":"The cook works in the kitchen and prepares delicious dishes.","prompt":"What is the feminine of cuoco?","answer":"cuoca","canDo":"I can combine early A1 grammar in short conversations.","canDoIt":"So combinare la grammatica A1 iniziale in brevi dialoghi.","summaryIt":"Consolida articoli, presente e professioni con recupero misto.","summaryEn":"In this lesson: I can combine early A1 grammar in short conversations.","grammarRuleIds":["articles","present","irregular"],"remember":[{"it":"Prima ascolta il suono, poi scegli l’articolo.","en":"The article depends on gender, number and initial sound."},{"it":"Segna sempre la famiglia del verbo.","en":"Remove -are, -ere or -ire and add the subject ending."},{"it":"Crea una frase personale per ogni forma difficile.","en":"Learn common irregular verbs as complete patterns."}],"writeDown":[{"it":"Frase modello: La cuoca lavora in cucina e prepara piatti deliziosi.","en":"Model sentence: The cook works in the kitchen and prepares delicious dishes."},{"it":"Regola chiave: L’articolo dipende da genere, numero e suono iniziale.","en":"Key rule: The article depends on gender, number and initial sound."},{"it":"Obiettivo personale: So combinare la grammatica A1 iniziale in brevi dialoghi.","en":"Personal goal: I can combine early A1 grammar in short conversations."}],"mistakes":[{"wrong":"il studente","right":"lo studente","noteIt":"Usa lo/gli prima di s+consonante, z, ps, gn, x e y; l’ prima di vocale.","noteEn":"Use lo/gli before special consonant clusters; l’ before a vowel."},{"wrong":"Io lavorare a Londra.","right":"Io lavoro a Londra.","noteIt":"Alcuni -ire aggiungono -isc-: preferisco.","noteEn":"Some -ire verbs add -isc-."}],"sourceRefs":["Archivio PDF · Primo ripasso","CELI A1 · competenze richieste","CILS A1 · descrittori"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c1w11', 'lesson', 'c1w11', 8, '{"id":"c1w11","course":1,"week":"11","title":"La giornata speciale","subtitle":"Routines, possessives & wishes","topics":["reflexives","possessives","fare"],"italian":"La mattina mi sveglio presto e faccio colazione.","english":"In the morning I wake up early and have breakfast.","prompt":"Complete: Questa è ___ sorella. (my)","answer":"mia sorella","canDo":"I can describe a routine, possessions and celebrations.","canDoIt":"So descrivere una routine, i miei oggetti e una festa.","summaryIt":"Racconta routine e desideri con riflessivi, possessivi e fare.","summaryEn":"In this lesson: I can describe a routine, possessions and celebrations.","grammarRuleIds":["reflexives","possessives","irregular"],"remember":[{"it":"Scrivi il pronome prima di coniugare.","en":"The reflexive pronoun changes with the subject."},{"it":"Chiediti quale nome è posseduto.","en":"The possessive agrees with the possessed thing."},{"it":"Crea una frase personale per ogni forma difficile.","en":"Learn common irregular verbs as complete patterns."}],"writeDown":[{"it":"Frase modello: La mattina mi sveglio presto e faccio colazione.","en":"Model sentence: In the morning I wake up early and have breakfast."},{"it":"Regola chiave: Il pronome cambia con il soggetto: mi, ti, si, ci, vi, si.","en":"Key rule: The reflexive pronoun changes with the subject."},{"it":"Obiettivo personale: So descrivere una routine, i miei oggetti e una festa.","en":"Personal goal: I can describe a routine, possessions and celebrations."}],"mistakes":[{"wrong":"Chiamo Samuel.","right":"Mi chiamo Samuel.","noteIt":"Con un modale: posso alzarmi oppure mi posso alzare.","noteEn":"With a modal, attach or place the pronoun before it."},{"wrong":"la mia madre","right":"mia madre","noteIt":"Di solito c’è l’articolo; spesso manca con un parente singolare non modificato.","noteEn":"The article is often omitted with an unmodified singular family member."}],"sourceRefs":["Archivio PDF · La giornata speciale","CELI A1 · competenze richieste","CILS A1 · descrittori"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c1w12', 'lesson', 'c1w12', 9, '{"id":"c1w12","course":1,"week":"12","title":"In città","subtitle":"Town & modal verbs","topics":["potere / dovere / volere","partitive","ci"],"italian":"Devo andare in farmacia; sai dov’è?","english":"I have to go to the pharmacy; do you know where it is?","prompt":"Choose: Conosco / So parlare italiano.","answer":"So parlare italiano.","canDo":"I can ask for directions and express wants, duties and abilities.","canDoIt":"So chiedere indicazioni ed esprimere desideri, obblighi e capacità.","summaryIt":"Chiedi indicazioni e usa modali, partitivo, sapere e conoscere.","summaryEn":"In this lesson: I can ask for directions and express wants, duties and abilities.","grammarRuleIds":["modals","partitive","sapere-conoscere","prepositions"],"remember":[{"it":"Formula: modale coniugato + infinito.","en":"Conjugate the modal and keep the second verb infinitive."},{"it":"Decidi: quantità vaga o misura precisa?","en":"Partitives express unspecified quantities."},{"it":"Fatto o capacità = sapere; persona o luogo = conoscere.","en":"Sapere concerns facts/know-how; conoscere familiarity."}],"writeDown":[{"it":"Frase modello: Devo andare in farmacia; sai dov’è?","en":"Model sentence: I have to go to the pharmacy; do you know where it is?"},{"it":"Regola chiave: Coniugo il modale e lascio il secondo verbo all’infinito.","en":"Key rule: Conjugate the modal and keep the second verb infinitive."},{"it":"Obiettivo personale: So chiedere indicazioni ed esprimere desideri, obblighi e capacità.","en":"Personal goal: I can ask for directions and express wants, duties and abilities."}],"mistakes":[{"wrong":"Voglio prenoto.","right":"Voglio prenotare.","noteIt":"Non coniugare entrambi i verbi.","noteEn":"Do not conjugate both verbs."},{"wrong":"un chilo della pasta","right":"un chilo di pasta","noteIt":"Dopo una misura precisa uso di.","noteEn":"Use di after an exact measure."}],"sourceRefs":["Archivio PDF · In città","CELI A1 · competenze richieste","CILS A1 · descrittori"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c1w13', 'lesson', 'c1w13', 10, '{"id":"c1w13","course":1,"week":"13","title":"Il passato","subtitle":"Passato prossimo","topics":["avere vs essere","participles","agreement"],"italian":"Ieri sono andato al mercato e ho comprato del pane.","english":"Yesterday I went to the market and bought some bread.","prompt":"Complete: Marta è ___ a casa. (return)","answer":"Marta è tornata a casa.","canDo":"I can report a short sequence of completed past events.","canDoIt":"So raccontare una breve sequenza di eventi conclusi.","summaryIt":"Racconta esperienze scegliendo ausiliare, participio e concordanza.","summaryEn":"In this lesson: I can report a short sequence of completed past events.","grammarRuleIds":["past","agreement"],"remember":[{"it":"Impara participio e ausiliare insieme.","en":"Use present avere/essere plus a past participle."},{"it":"Controlla l’ultima lettera di nome e aggettivo.","en":"The adjective agrees with the noun in gender and number."}],"writeDown":[{"it":"Frase modello: Ieri sono andato al mercato e ho comprato del pane.","en":"Model sentence: Yesterday I went to the market and bought some bread."},{"it":"Regola chiave: Uso il presente di avere o essere più il participio passato.","en":"Key rule: Use present avere/essere plus a past participle."},{"it":"Obiettivo personale: So raccontare una breve sequenza di eventi conclusi.","en":"Personal goal: I can report a short sequence of completed past events."}],"mistakes":[{"wrong":"Maria è andato.","right":"Maria è andata.","noteIt":"Con essere il participio concorda; i riflessivi usano essere.","noteEn":"With essere the participle agrees; reflexives use essere."},{"wrong":"due case grande","right":"due case grandi","noteIt":"Gli aggettivi in -e hanno il plurale in -i.","noteEn":"Adjectives ending in -e form the plural in -i."}],"sourceRefs":["Archivio PDF · Il passato","CELI A1 · competenze richieste","CILS A1 · descrittori"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c1w13b', 'lesson', 'c1w13b', 11, '{"id":"c1w13b","course":1,"week":"13b","title":"Sessione di ripasso","subtitle":"Revision workshop","topics":["mixed grammar","reading","games"],"italian":"Ripassiamo gli articoli, i verbi e le preposizioni.","english":"Let’s review articles, verbs and prepositions.","prompt":"Complete: Vado ___ cinema.","answer":"Vado al cinema.","canDo":"I can switch between mixed A1 grammar under time pressure.","canDoIt":"So passare tra diversi argomenti A1 sotto pressione.","summaryIt":"Mescola grammatica, lettura e produzione senza indizi di capitolo.","summaryEn":"In this lesson: I can switch between mixed A1 grammar under time pressure.","grammarRuleIds":["articles","present","past"],"remember":[{"it":"Prima ascolta il suono, poi scegli l’articolo.","en":"The article depends on gender, number and initial sound."},{"it":"Segna sempre la famiglia del verbo.","en":"Remove -are, -ere or -ire and add the subject ending."},{"it":"Impara participio e ausiliare insieme.","en":"Use present avere/essere plus a past participle."}],"writeDown":[{"it":"Frase modello: Ripassiamo gli articoli, i verbi e le preposizioni.","en":"Model sentence: Let’s review articles, verbs and prepositions."},{"it":"Regola chiave: L’articolo dipende da genere, numero e suono iniziale.","en":"Key rule: The article depends on gender, number and initial sound."},{"it":"Obiettivo personale: So passare tra diversi argomenti A1 sotto pressione.","en":"Personal goal: I can switch between mixed A1 grammar under time pressure."}],"mistakes":[{"wrong":"il studente","right":"lo studente","noteIt":"Usa lo/gli prima di s+consonante, z, ps, gn, x e y; l’ prima di vocale.","noteEn":"Use lo/gli before special consonant clusters; l’ before a vowel."},{"wrong":"Io lavorare a Londra.","right":"Io lavoro a Londra.","noteIt":"Alcuni -ire aggiungono -isc-: preferisco.","noteEn":"Some -ire verbs add -isc-."}],"sourceRefs":["Archivio PDF · Sessione di ripasso","CELI A1 · competenze richieste","CILS A1 · descrittori"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c1w14', 'lesson', 'c1w14', 12, '{"id":"c1w14","course":1,"week":"14","title":"I pronomi diretti","subtitle":"Direct object pronouns","topics":["lo / la / li / le","pronoun position","verbs"],"italian":"Compri le mele? Sì, le compro.","english":"Are you buying the apples? Yes, I’m buying them.","prompt":"Replace: Mangio la pizza.","answer":"La mangio.","canDo":"I can avoid repetition with direct object pronouns.","canDoIt":"So evitare ripetizioni usando i pronomi diretti.","summaryIt":"Sostituisci oggetti noti con lo, la, li e le e posiziona il pronome.","summaryEn":"In this lesson: I can avoid repetition with direct object pronouns.","grammarRuleIds":["direct-pronouns","agreement"],"remember":[{"it":"Trova genere e numero dell’oggetto.","en":"Direct object pronouns replace a known object and precede the verb."},{"it":"Controlla l’ultima lettera di nome e aggettivo.","en":"The adjective agrees with the noun in gender and number."}],"writeDown":[{"it":"Frase modello: Compri le mele? Sì, le compro.","en":"Model sentence: Are you buying the apples? Yes, I’m buying them."},{"it":"Regola chiave: Lo, la, li e le sostituiscono un oggetto noto e precedono il verbo.","en":"Key rule: Direct object pronouns replace a known object and precede the verb."},{"it":"Obiettivo personale: So evitare ripetizioni usando i pronomi diretti.","en":"Personal goal: I can avoid repetition with direct object pronouns."}],"mistakes":[{"wrong":"Vedo la ogni giorno.","right":"La vedo ogni giorno.","noteIt":"Davanti a vocale lo/la possono diventare l’.","noteEn":"Before a vowel lo/la may become l’."},{"wrong":"due case grande","right":"due case grandi","noteIt":"Gli aggettivi in -e hanno il plurale in -i.","noteEn":"Adjectives ending in -e form the plural in -i."}],"sourceRefs":["Archivio PDF · I pronomi diretti","CELI A1 · competenze richieste","CILS A1 · descrittori"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c1w15', 'lesson', 'c1w15', 13, '{"id":"c1w15","course":1,"week":"15","title":"Al supermercato","subtitle":"Food shopping","topics":["partitive","quantities","shopping"],"italian":"Vorrei due etti di prosciutto e del formaggio.","english":"I’d like two hundred grams of ham and some cheese.","prompt":"Choose: del / della pasta.","answer":"della pasta","canDo":"I can shop for food using quantities and partitives.","canDoIt":"So comprare cibo usando quantità e partitivi.","summaryIt":"Fai la spesa ed esprimi quantità precise o indefinite.","summaryEn":"In this lesson: I can shop for food using quantities and partitives.","grammarRuleIds":["partitive","ordering","plurals"],"remember":[{"it":"Decidi: quantità vaga o misura precisa?","en":"Partitives express unspecified quantities."},{"it":"Aggiungi per favore e chiudi con grazie.","en":"Order with vorrei, prendo, per me and posso avere."},{"it":"Impara nome, articolo e plurale insieme.","en":"Usually -o→-i, -a→-e and -e→-i."}],"writeDown":[{"it":"Frase modello: Vorrei due etti di prosciutto e del formaggio.","en":"Model sentence: I’d like two hundred grams of ham and some cheese."},{"it":"Regola chiave: Del, dello, della, dei, degli e delle indicano quantità non precise.","en":"Key rule: Partitives express unspecified quantities."},{"it":"Obiettivo personale: So comprare cibo usando quantità e partitivi.","en":"Personal goal: I can shop for food using quantities and partitives."}],"mistakes":[{"wrong":"un chilo della pasta","right":"un chilo di pasta","noteIt":"Dopo una misura precisa uso di.","noteEn":"Use di after an exact measure."},{"wrong":"Voglio un’acqua!","right":"Vorrei un’acqua, per favore.","noteIt":"Vorrei è più cortese di voglio.","noteEn":"Vorrei is more polite than voglio."}],"sourceRefs":["Archivio PDF · Al supermercato","CELI A1 · competenze richieste","CILS A1 · descrittori"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c1w16', 'lesson', 'c1w16', 14, '{"id":"c1w16","course":1,"week":"16","title":"La famiglia","subtitle":"Family","topics":["possessives","descriptions","family"],"italian":"Mio fratello è alto e molto simpatico.","english":"My brother is tall and very nice.","prompt":"Why no article in ‘mia madre’?","answer":"Singular, unmodified close family members normally omit the article.","canDo":"I can describe my family and relationships.","canDoIt":"So descrivere la mia famiglia e le relazioni.","summaryIt":"Presenta la famiglia e applica le eccezioni dei possessivi.","summaryEn":"In this lesson: I can describe my family and relationships.","grammarRuleIds":["possessives","agreement","articles"],"remember":[{"it":"Chiediti quale nome è posseduto.","en":"The possessive agrees with the possessed thing."},{"it":"Controlla l’ultima lettera di nome e aggettivo.","en":"The adjective agrees with the noun in gender and number."},{"it":"Prima ascolta il suono, poi scegli l’articolo.","en":"The article depends on gender, number and initial sound."}],"writeDown":[{"it":"Frase modello: Mio fratello è alto e molto simpatico.","en":"Model sentence: My brother is tall and very nice."},{"it":"Regola chiave: Il possessivo concorda con la cosa posseduta, non con il proprietario.","en":"Key rule: The possessive agrees with the possessed thing."},{"it":"Obiettivo personale: So descrivere la mia famiglia e le relazioni.","en":"Personal goal: I can describe my family and relationships."}],"mistakes":[{"wrong":"la mia madre","right":"mia madre","noteIt":"Di solito c’è l’articolo; spesso manca con un parente singolare non modificato.","noteEn":"The article is often omitted with an unmodified singular family member."},{"wrong":"due case grande","right":"due case grandi","noteIt":"Gli aggettivi in -e hanno il plurale in -i.","noteEn":"Adjectives ending in -e form the plural in -i."}],"sourceRefs":["Archivio PDF · La famiglia","CELI A1 · competenze richieste","CILS A1 · descrittori"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c1w17', 'lesson', 'c1w17', 15, '{"id":"c1w17","course":1,"week":"17","title":"Passaporto e identità","subtitle":"Identity details","topics":["personal details","nationalities","forms"],"italian":"Sono nato a Londra il dodici maggio.","english":"I was born in London on the twelfth of May.","prompt":"Ask: Where were you born?","answer":"Dove sei nato / nata?","canDo":"I can give identity details and complete a simple form.","canDoIt":"So fornire dati personali e compilare un modulo semplice.","summaryIt":"Compila moduli e comunica identità e contatti con precisione.","summaryEn":"In this lesson: I can give identity details and complete a simple form.","grammarRuleIds":["forms","essere","agreement"],"remember":[{"it":"Controlla due volte numeri e grafia.","en":"Recognise standard fields for personal details."},{"it":"Ricorda: sono, sei, è, siamo, siete, sono.","en":"Use essere for identity, origin, qualities and location."},{"it":"Controlla l’ultima lettera di nome e aggettivo.","en":"The adjective agrees with the noun in gender and number."}],"writeDown":[{"it":"Frase modello: Sono nato a Londra il dodici maggio.","en":"Model sentence: I was born in London on the twelfth of May."},{"it":"Regola chiave: Riconosco cognome, nome, nascita, nazionalità, indirizzo e firma.","en":"Key rule: Recognise standard fields for personal details."},{"it":"Obiettivo personale: So fornire dati personali e compilare un modulo semplice.","en":"Personal goal: I can give identity details and complete a simple form."}],"mistakes":[{"wrong":"Sono nato il data 12/05.","right":"Data di nascita: 12/05.","noteIt":"Nei campi brevi non servono frasi complete.","noteEn":"Short form fields need not be full sentences."},{"wrong":"Io è inglese.","right":"Io sono inglese.","noteIt":"La nazionalità concorda: italiano/italiana.","noteEn":"Nationality agrees in gender."}],"sourceRefs":["Archivio PDF · Passaporto e identità","CELI A1 · competenze richieste","CILS A1 · descrittori"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c1w18', 'lesson', 'c1w18', 16, '{"id":"c1w18","course":1,"week":"18","title":"Descrivere e proporre","subtitle":"Revision & proposals","topics":["appearance","possessives","proposals","past"],"italian":"Perché non andiamo al museo domenica?","english":"Why don’t we go to the museum on Sunday?","prompt":"Accept enthusiastically.","answer":"Sì, volentieri!","canDo":"I can describe people and make simple proposals.","canDoIt":"So descrivere le persone e fare proposte semplici.","summaryIt":"Descrivi persone, fai proposte e collega presente e passato.","summaryEn":"In this lesson: I can describe people and make simple proposals.","grammarRuleIds":["agreement","invitations","past"],"remember":[{"it":"Controlla l’ultima lettera di nome e aggettivo.","en":"The adjective agrees with the noun in gender and number."},{"it":"Prepara un sì e un no cortese.","en":"Use common invitation frames to suggest plans."},{"it":"Impara participio e ausiliare insieme.","en":"Use present avere/essere plus a past participle."}],"writeDown":[{"it":"Frase modello: Perché non andiamo al museo domenica?","en":"Model sentence: Why don’t we go to the museum on Sunday?"},{"it":"Regola chiave: L’aggettivo concorda con il nome in genere e numero.","en":"Key rule: The adjective agrees with the noun in gender and number."},{"it":"Obiettivo personale: So descrivere le persone e fare proposte semplici.","en":"Personal goal: I can describe people and make simple proposals."}],"mistakes":[{"wrong":"due case grande","right":"due case grandi","noteIt":"Gli aggettivi in -e hanno il plurale in -i.","noteEn":"Adjectives ending in -e form the plural in -i."},{"wrong":"Ti va di ceni fuori?","right":"Ti va di cenare fuori?","noteIt":"Dopo di uso l’infinito.","noteEn":"Use an infinitive after di."}],"sourceRefs":["Archivio PDF · Descrivere e proporre","CELI A1 · competenze richieste","CILS A1 · descrittori"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c1w19', 'lesson', 'c1w19', 17, '{"id":"c1w19","course":1,"week":"19","title":"La routine quotidiana","subtitle":"Daily routine","topics":["reflexive verbs","time","frequency"],"italian":"Di solito mi alzo alle sette e mezza.","english":"I usually get up at half past seven.","prompt":"Conjugate svegliarsi for noi.","answer":"noi ci svegliamo","canDo":"I can describe my daily routine with times and frequency.","canDoIt":"So descrivere la mia routine con orari e frequenza.","summaryIt":"Racconta una giornata in ordine con riflessivi, orari e frequenza.","summaryEn":"In this lesson: I can describe my daily routine with times and frequency.","grammarRuleIds":["reflexives","time","frequency"],"remember":[{"it":"Scrivi il pronome prima di coniugare.","en":"The reflexive pronoun changes with the subject."},{"it":"Distingui Che ore sono? da A che ora...?","en":"Say è l’una but sono le due, le tre, and so on."},{"it":"Ordina gli avverbi da sempre a mai.","en":"Use frequency adverbs close to the verb."}],"writeDown":[{"it":"Frase modello: Di solito mi alzo alle sette e mezza.","en":"Model sentence: I usually get up at half past seven."},{"it":"Regola chiave: Il pronome cambia con il soggetto: mi, ti, si, ci, vi, si.","en":"Key rule: The reflexive pronoun changes with the subject."},{"it":"Obiettivo personale: So descrivere la mia routine con orari e frequenza.","en":"Personal goal: I can describe my daily routine with times and frequency."}],"mistakes":[{"wrong":"Chiamo Samuel.","right":"Mi chiamo Samuel.","noteIt":"Con un modale: posso alzarmi oppure mi posso alzare.","noteEn":"With a modal, attach or place the pronoun before it."},{"wrong":"È le nove.","right":"Sono le nove.","noteIt":"Per orari: all’una, alle otto.","noteEn":"For scheduled times: all’una, alle otto."}],"sourceRefs":["Archivio PDF · La routine quotidiana","CELI A1 · competenze richieste","CILS A1 · descrittori"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c1w20', 'lesson', 'c1w20', 18, '{"id":"c1w20","course":1,"week":"20","title":"La casa","subtitle":"Estate & property","topics":["rooms","c’è / ci sono","prepositions","renting"],"italian":"Nell’appartamento ci sono due camere e un balcone.","english":"There are two bedrooms and a balcony in the flat.","prompt":"Ask whether bills are included.","answer":"Le spese sono incluse?","canDo":"I can understand a rental advert and ask key questions.","canDoIt":"So capire un annuncio immobiliare e fare domande essenziali.","summaryIt":"Descrivi casa e quartiere e poni domande essenziali per un affitto.","summaryEn":"In this lesson: I can understand a rental advert and ask key questions.","grammarRuleIds":["ce-ci-sono","articulated-preps","prepositions"],"remember":[{"it":"Conta il nome prima di scegliere.","en":"Use c’è for one thing and ci sono for more than one."},{"it":"Scomponi: a + lo = allo; in + la = nella.","en":"Di, a, da, in and su combine with the article."},{"it":"Impara la preposizione dentro una frase.","en":"Simple prepositions express different relationships."}],"writeDown":[{"it":"Frase modello: Nell’appartamento ci sono due camere e un balcone.","en":"Model sentence: There are two bedrooms and a balcony in the flat."},{"it":"Regola chiave: Uso c’è per una cosa e ci sono per più cose.","en":"Key rule: Use c’è for one thing and ci sono for more than one."},{"it":"Obiettivo personale: So capire un annuncio immobiliare e fare domande essenziali.","en":"Personal goal: I can understand a rental advert and ask key questions."}],"mistakes":[{"wrong":"C’è tre finestre.","right":"Ci sono tre finestre.","noteIt":"Nelle domande mantengo la stessa forma.","noteEn":"Questions retain the same form."},{"wrong":"Vado al stadio.","right":"Vado allo stadio.","noteIt":"Trova prima l’articolo del nome.","noteEn":"Find the noun’s article first."}],"sourceRefs":["Archivio PDF · La casa","CELI A1 · competenze richieste","CILS A1 · descrittori"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c2w01', 'lesson', 'c2w01', 19, '{"id":"c2w01","course":2,"week":"01","title":"Presentazioni","subtitle":"Introductions revisited","topics":["essere","regular verbs","piacere","reflexives"],"italian":"Mi chiamo Guglielmo, vivo a Londra e studio italiano.","english":"My name is Guglielmo, I live in London and I study Italian.","prompt":"Introduce yourself in three clauses.","answer":"Mi chiamo…, vivo a… e studio / lavoro…","canDo":"I can give a one-minute personal introduction.","canDoIt":"So presentarmi per un minuto.","summaryIt":"Rendi automatiche presentazioni che uniscono identità, azioni e gusti.","summaryEn":"In this lesson: I can give a one-minute personal introduction.","grammarRuleIds":["essere","present","piacere","reflexives"],"remember":[{"it":"Ricorda: sono, sei, è, siamo, siete, sono.","en":"Use essere for identity, origin, qualities and location."},{"it":"Segna sempre la famiglia del verbo.","en":"Remove -are, -ere or -ire and add the subject ending."},{"it":"Guarda la cosa dopo il verbo.","en":"The liked thing controls the verb."}],"writeDown":[{"it":"Frase modello: Mi chiamo Guglielmo, vivo a Londra e studio italiano.","en":"Model sentence: My name is Guglielmo, I live in London and I study Italian."},{"it":"Regola chiave: Uso essere per identità, origine, qualità e posizione.","en":"Key rule: Use essere for identity, origin, qualities and location."},{"it":"Obiettivo personale: So presentarmi per un minuto.","en":"Personal goal: I can give a one-minute personal introduction."}],"mistakes":[{"wrong":"Io è inglese.","right":"Io sono inglese.","noteIt":"La nazionalità concorda: italiano/italiana.","noteEn":"Nationality agrees in gender."},{"wrong":"Io lavorare a Londra.","right":"Io lavoro a Londra.","noteIt":"Alcuni -ire aggiungono -isc-: preferisco.","noteEn":"Some -ire verbs add -isc-."}],"sourceRefs":["Archivio PDF · Presentazioni","CELI A1 · competenze richieste","CILS A1 · descrittori"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c2w02', 'lesson', 'c2w02', 20, '{"id":"c2w02","course":2,"week":"02","title":"La famiglia","subtitle":"Possessives & family","topics":["possessives","relationships","agreement"],"italian":"I miei genitori abitano vicino ai miei nonni.","english":"My parents live near my grandparents.","prompt":"Complete: ___ cugine sono italiane. (our)","answer":"Le nostre cugine","canDo":"I can describe my family using accurate possessives.","canDoIt":"So descrivere la famiglia usando correttamente i possessivi.","summaryIt":"Approfondisci famiglia e relazioni con possessivi e accordo.","summaryEn":"In this lesson: I can describe my family using accurate possessives.","grammarRuleIds":["possessives","agreement","articles"],"remember":[{"it":"Chiediti quale nome è posseduto.","en":"The possessive agrees with the possessed thing."},{"it":"Controlla l’ultima lettera di nome e aggettivo.","en":"The adjective agrees with the noun in gender and number."},{"it":"Prima ascolta il suono, poi scegli l’articolo.","en":"The article depends on gender, number and initial sound."}],"writeDown":[{"it":"Frase modello: I miei genitori abitano vicino ai miei nonni.","en":"Model sentence: My parents live near my grandparents."},{"it":"Regola chiave: Il possessivo concorda con la cosa posseduta, non con il proprietario.","en":"Key rule: The possessive agrees with the possessed thing."},{"it":"Obiettivo personale: So descrivere la famiglia usando correttamente i possessivi.","en":"Personal goal: I can describe my family using accurate possessives."}],"mistakes":[{"wrong":"la mia madre","right":"mia madre","noteIt":"Di solito c’è l’articolo; spesso manca con un parente singolare non modificato.","noteEn":"The article is often omitted with an unmodified singular family member."},{"wrong":"due case grande","right":"due case grandi","noteIt":"Gli aggettivi in -e hanno il plurale in -i.","noteEn":"Adjectives ending in -e form the plural in -i."}],"sourceRefs":["Archivio PDF · La famiglia","CELI A1 · competenze richieste","CILS A1 · descrittori"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c2w03', 'lesson', 'c2w03', 21, '{"id":"c2w03","course":2,"week":"03","title":"Il mondo del lavoro","subtitle":"Jobs & workplaces","topics":["articles","plurals","workplaces","reading"],"italian":"L’infermiera lavora in ospedale e aiuta i pazienti.","english":"The nurse works in a hospital and helps patients.","prompt":"Plural: il giornalista.","answer":"i giornalisti","canDo":"I can understand and discuss familiar jobs and workplaces.","canDoIt":"So capire e discutere lavori e luoghi di lavoro familiari.","summaryIt":"Collega professioni, luoghi, articoli e plurali in testi brevi.","summaryEn":"In this lesson: I can understand and discuss familiar jobs and workplaces.","grammarRuleIds":["articles","plurals","present"],"remember":[{"it":"Prima ascolta il suono, poi scegli l’articolo.","en":"The article depends on gender, number and initial sound."},{"it":"Impara nome, articolo e plurale insieme.","en":"Usually -o→-i, -a→-e and -e→-i."},{"it":"Segna sempre la famiglia del verbo.","en":"Remove -are, -ere or -ire and add the subject ending."}],"writeDown":[{"it":"Frase modello: L’infermiera lavora in ospedale e aiuta i pazienti.","en":"Model sentence: The nurse works in a hospital and helps patients."},{"it":"Regola chiave: L’articolo dipende da genere, numero e suono iniziale.","en":"Key rule: The article depends on gender, number and initial sound."},{"it":"Obiettivo personale: So capire e discutere lavori e luoghi di lavoro familiari.","en":"Personal goal: I can understand and discuss familiar jobs and workplaces."}],"mistakes":[{"wrong":"il studente","right":"lo studente","noteIt":"Usa lo/gli prima di s+consonante, z, ps, gn, x e y; l’ prima di vocale.","noteEn":"Use lo/gli before special consonant clusters; l’ before a vowel."},{"wrong":"le cittàs","right":"le città","noteIt":"Parole straniere e accentate spesso non cambiano: i bar, le città.","noteEn":"Foreign and stressed-final words are often invariable."}],"sourceRefs":["Archivio PDF · Il mondo del lavoro","CELI A1 · competenze richieste","CILS A1 · descrittori"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c2w04', 'lesson', 'c2w04', 22, '{"id":"c2w04","course":2,"week":"04","title":"Routine e corpo umano","subtitle":"Daily routine & the body","topics":["reflexives","body","irregular plurals","song"],"italian":"Mi lavo le mani e poi mi pettino i capelli.","english":"I wash my hands and then comb my hair.","prompt":"Plural of il braccio?","answer":"le braccia","canDo":"I can describe a routine and basic parts of the body.","canDoIt":"So descrivere una routine e le parti principali del corpo.","summaryIt":"Parla di routine e corpo con riflessivi e plurali irregolari.","summaryEn":"In this lesson: I can describe a routine and basic parts of the body.","grammarRuleIds":["reflexives","plurals","time"],"remember":[{"it":"Scrivi il pronome prima di coniugare.","en":"The reflexive pronoun changes with the subject."},{"it":"Impara nome, articolo e plurale insieme.","en":"Usually -o→-i, -a→-e and -e→-i."},{"it":"Distingui Che ore sono? da A che ora...?","en":"Say è l’una but sono le due, le tre, and so on."}],"writeDown":[{"it":"Frase modello: Mi lavo le mani e poi mi pettino i capelli.","en":"Model sentence: I wash my hands and then comb my hair."},{"it":"Regola chiave: Il pronome cambia con il soggetto: mi, ti, si, ci, vi, si.","en":"Key rule: The reflexive pronoun changes with the subject."},{"it":"Obiettivo personale: So descrivere una routine e le parti principali del corpo.","en":"Personal goal: I can describe a routine and basic parts of the body."}],"mistakes":[{"wrong":"Chiamo Samuel.","right":"Mi chiamo Samuel.","noteIt":"Con un modale: posso alzarmi oppure mi posso alzare.","noteEn":"With a modal, attach or place the pronoun before it."},{"wrong":"le cittàs","right":"le città","noteIt":"Parole straniere e accentate spesso non cambiano: i bar, le città.","noteEn":"Foreign and stressed-final words are often invariable."}],"sourceRefs":["Archivio PDF · Routine e corpo umano","CELI A1 · competenze richieste","CILS A1 · descrittori"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c2w05', 'lesson', 'c2w05', 23, '{"id":"c2w05","course":2,"week":"05","title":"In città","subtitle":"Town & reflexive verbs","topics":["directions","reflexives","opposites"],"italian":"La banca è di fronte alla farmacia.","english":"The bank is opposite the pharmacy.","prompt":"Translate: next to the station.","answer":"accanto alla stazione","canDo":"I can locate places and follow simple directions.","canDoIt":"So localizzare luoghi e seguire indicazioni semplici.","summaryIt":"Orientati in città e dai indicazioni precise in contesto.","summaryEn":"In this lesson: I can locate places and follow simple directions.","grammarRuleIds":["prepositions","articulated-preps","reflexives"],"remember":[{"it":"Impara la preposizione dentro una frase.","en":"Simple prepositions express different relationships."},{"it":"Scomponi: a + lo = allo; in + la = nella.","en":"Di, a, da, in and su combine with the article."},{"it":"Scrivi il pronome prima di coniugare.","en":"The reflexive pronoun changes with the subject."}],"writeDown":[{"it":"Frase modello: La banca è di fronte alla farmacia.","en":"Model sentence: The bank is opposite the pharmacy."},{"it":"Regola chiave: Di, a, da, in, con, su, per e tra/fra esprimono relazioni diverse.","en":"Key rule: Simple prepositions express different relationships."},{"it":"Obiettivo personale: So localizzare luoghi e seguire indicazioni semplici.","en":"Personal goal: I can locate places and follow simple directions."}],"mistakes":[{"wrong":"Vivo a Italia.","right":"Vivo in Italia.","noteIt":"Con città uso spesso a; con paesi uso spesso in.","noteEn":"Often use a with cities and in with countries."},{"wrong":"Vado al stadio.","right":"Vado allo stadio.","noteIt":"Trova prima l’articolo del nome.","noteEn":"Find the noun’s article first."}],"sourceRefs":["Archivio PDF · In città","CELI A1 · competenze richieste","CILS A1 · descrittori"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c2w06', 'lesson', 'c2w06', 24, '{"id":"c2w06","course":2,"week":"06","title":"Al bar e al ristorante","subtitle":"Ordering with confidence","topics":["ordering","articles","verbs","quick test"],"italian":"Per me gli gnocchi; da bere, dell’acqua frizzante.","english":"Gnocchi for me; sparkling water to drink.","prompt":"Politely order a starter.","answer":"Come antipasto, vorrei…","canDo":"I can manage a complete restaurant interaction.","canDoIt":"So gestire un’interazione completa al ristorante.","summaryIt":"Gestisci un pasto dall’ingresso al conto con richieste cortesi.","summaryEn":"In this lesson: I can manage a complete restaurant interaction.","grammarRuleIds":["ordering","articles","modals"],"remember":[{"it":"Aggiungi per favore e chiudi con grazie.","en":"Order with vorrei, prendo, per me and posso avere."},{"it":"Prima ascolta il suono, poi scegli l’articolo.","en":"The article depends on gender, number and initial sound."},{"it":"Formula: modale coniugato + infinito.","en":"Conjugate the modal and keep the second verb infinitive."}],"writeDown":[{"it":"Frase modello: Per me gli gnocchi; da bere, dell’acqua frizzante.","en":"Model sentence: Gnocchi for me; sparkling water to drink."},{"it":"Regola chiave: Per ordinare uso vorrei, prendo, per me e posso avere.","en":"Key rule: Order with vorrei, prendo, per me and posso avere."},{"it":"Obiettivo personale: So gestire un’interazione completa al ristorante.","en":"Personal goal: I can manage a complete restaurant interaction."}],"mistakes":[{"wrong":"Voglio un’acqua!","right":"Vorrei un’acqua, per favore.","noteIt":"Vorrei è più cortese di voglio.","noteEn":"Vorrei is more polite than voglio."},{"wrong":"il studente","right":"lo studente","noteIt":"Usa lo/gli prima di s+consonante, z, ps, gn, x e y; l’ prima di vocale.","noteEn":"Use lo/gli before special consonant clusters; l’ before a vowel."}],"sourceRefs":["Archivio PDF · Al bar e al ristorante","CELI A1 · competenze richieste","CILS A1 · descrittori"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c2w07', 'lesson', 'c2w07', 25, '{"id":"c2w07","course":2,"week":"07","title":"Preposizioni","subtitle":"Grammar revision","topics":["simple prepositions","articulated prepositions","Tutti Frutti"],"italian":"Vado in biblioteca, ma studio nella Biblioteca Centrale.","english":"I go to the library, but I study in the Central Library.","prompt":"Combine: su + gli scaffali.","answer":"sugli scaffali","canDo":"I can select simple or articulated prepositions accurately.","canDoIt":"So scegliere correttamente preposizioni semplici e articolate.","summaryIt":"Costruisci preposizioni semplici e articolate spiegandone la logica.","summaryEn":"In this lesson: I can select simple or articulated prepositions accurately.","grammarRuleIds":["prepositions","articulated-preps","articles"],"remember":[{"it":"Impara la preposizione dentro una frase.","en":"Simple prepositions express different relationships."},{"it":"Scomponi: a + lo = allo; in + la = nella.","en":"Di, a, da, in and su combine with the article."},{"it":"Prima ascolta il suono, poi scegli l’articolo.","en":"The article depends on gender, number and initial sound."}],"writeDown":[{"it":"Frase modello: Vado in biblioteca, ma studio nella Biblioteca Centrale.","en":"Model sentence: I go to the library, but I study in the Central Library."},{"it":"Regola chiave: Di, a, da, in, con, su, per e tra/fra esprimono relazioni diverse.","en":"Key rule: Simple prepositions express different relationships."},{"it":"Obiettivo personale: So scegliere correttamente preposizioni semplici e articolate.","en":"Personal goal: I can select simple or articulated prepositions accurately."}],"mistakes":[{"wrong":"Vivo a Italia.","right":"Vivo in Italia.","noteIt":"Con città uso spesso a; con paesi uso spesso in.","noteEn":"Often use a with cities and in with countries."},{"wrong":"Vado al stadio.","right":"Vado allo stadio.","noteIt":"Trova prima l’articolo del nome.","noteEn":"Find the noun’s article first."}],"sourceRefs":["Archivio PDF · Preposizioni","CELI A1 · competenze richieste","CILS A1 · descrittori"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c2w08', 'lesson', 'c2w08', 26, '{"id":"c2w08","course":2,"week":"08","title":"Cibo e vestiti","subtitle":"Food, clothes & colours","topics":["food","clothes","colours","agreement"],"italian":"Cerco una camicia bianca e dei pantaloni neri.","english":"I’m looking for a white shirt and black trousers.","prompt":"Make plural: la scarpa rossa.","answer":"le scarpe rosse","canDo":"I can shop for food and clothes using colour agreement.","canDoIt":"So comprare cibo e vestiti accordando i colori.","summaryIt":"Descrivi cibo, abiti e colori con accordo ed eccezioni.","summaryEn":"In this lesson: I can shop for food and clothes using colour agreement.","grammarRuleIds":["colours","agreement","partitive"],"remember":[{"it":"Descrivi con articolo + nome + colore.","en":"Adjectival colours agree; some colours stay invariable."},{"it":"Controlla l’ultima lettera di nome e aggettivo.","en":"The adjective agrees with the noun in gender and number."},{"it":"Decidi: quantità vaga o misura precisa?","en":"Partitives express unspecified quantities."}],"writeDown":[{"it":"Frase modello: Cerco una camicia bianca e dei pantaloni neri.","en":"Model sentence: I’m looking for a white shirt and black trousers."},{"it":"Regola chiave: I colori aggettivali concordano; alcuni colori restano invariabili.","en":"Key rule: Adjectival colours agree; some colours stay invariable."},{"it":"Obiettivo personale: So comprare cibo e vestiti accordando i colori.","en":"Personal goal: I can shop for food and clothes using colour agreement."}],"mistakes":[{"wrong":"due pantaloni blui","right":"due pantaloni blu","noteIt":"Blu, rosa, viola e beige sono normalmente invariabili.","noteEn":"Blu, rosa, viola and beige are normally invariable."},{"wrong":"due case grande","right":"due case grandi","noteIt":"Gli aggettivi in -e hanno il plurale in -i.","noteEn":"Adjectives ending in -e form the plural in -i."}],"sourceRefs":["Archivio PDF · Cibo e vestiti","CELI A1 · competenze richieste","CILS A1 · descrittori"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c2w09', 'lesson', 'c2w09', 27, '{"id":"c2w09","course":2,"week":"09","title":"Albergo e progetti","subtitle":"Hotel problems & weekend plans","topics":["articulated prepositions","hotel","invitations","formal Lei"],"italian":"La card non funziona. Mi può aiutare, per favore?","english":"The key card doesn’t work. Can you help me, please?","prompt":"Suggest visiting a museum.","answer":"Ti va di visitare un museo? / Perché non visitiamo un museo?","canDo":"I can solve a hotel problem and negotiate weekend plans.","canDoIt":"So risolvere un problema in albergo e organizzare il fine settimana.","summaryIt":"Risolvi problemi in albergo e organizza piani con inviti e registro formale.","summaryEn":"In this lesson: I can solve a hotel problem and negotiate weekend plans.","grammarRuleIds":["articulated-preps","invitations","questions","modals"],"remember":[{"it":"Scomponi: a + lo = allo; in + la = nella.","en":"Di, a, da, in and su combine with the article."},{"it":"Prepara un sì e un no cortese.","en":"Use common invitation frames to suggest plans."},{"it":"Abbina ogni domanda all’informazione cercata.","en":"Use question words to request specific details."}],"writeDown":[{"it":"Frase modello: La card non funziona. Mi può aiutare, per favore?","en":"Model sentence: The key card doesn’t work. Can you help me, please?"},{"it":"Regola chiave: Di, a, da, in e su si fondono con l’articolo.","en":"Key rule: Di, a, da, in and su combine with the article."},{"it":"Obiettivo personale: So risolvere un problema in albergo e organizzare il fine settimana.","en":"Personal goal: I can solve a hotel problem and negotiate weekend plans."}],"mistakes":[{"wrong":"Vado al stadio.","right":"Vado allo stadio.","noteIt":"Trova prima l’articolo del nome.","noteEn":"Find the noun’s article first."},{"wrong":"Ti va di ceni fuori?","right":"Ti va di cenare fuori?","noteIt":"Dopo di uso l’infinito.","noteEn":"Use an infinitive after di."}],"sourceRefs":["Archivio PDF · Albergo e progetti","CELI A1 · competenze richieste","CILS A1 · descrittori"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('grammar_rule:essere', 'grammar_rule', NULL, 1400, '{"id":"essere","titleIt":"Essere: identità e origine","titleEn":"Essere: identity and origin","ruleIt":"Uso essere per identità, origine, qualità e posizione.","ruleEn":"Use essere for identity, origin, qualities and location.","examples":[{"it":"Sono inglese e sono di Londra.","en":"I am English and I am from London."}],"exceptionIt":"La nazionalità concorda: italiano/italiana.","exceptionEn":"Nationality agrees in gender.","mistake":{"wrong":"Io è inglese.","right":"Io sono inglese."},"rememberIt":"Ricorda: sono, sei, è, siamo, siete, sono."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('grammar_rule:avere', 'grammar_rule', NULL, 1401, '{"id":"avere","titleIt":"Avere e l’età","titleEn":"Avere and age","ruleIt":"Uso avere per età, possesso e molte sensazioni.","ruleEn":"Use avere for age, possession and many physical states.","examples":[{"it":"Ho trent’anni e ho fame.","en":"I am thirty and I am hungry."}],"exceptionIt":"In italiano l’età si ‘ha’.","exceptionEn":"In Italian you ‘have’ an age.","mistake":{"wrong":"Sono venticinque anni.","right":"Ho venticinque anni."},"rememberIt":"Memorizza: ho, hai, ha, abbiamo, avete, hanno."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('grammar_rule:articles', 'grammar_rule', NULL, 1402, '{"id":"articles","titleIt":"Articoli: scegli con il suono","titleEn":"Articles: choose by sound","ruleIt":"L’articolo dipende da genere, numero e suono iniziale.","ruleEn":"The article depends on gender, number and initial sound.","examples":[{"it":"lo studente → gli studenti","en":"the student → the students"}],"exceptionIt":"Usa lo/gli prima di s+consonante, z, ps, gn, x e y; l’ prima di vocale.","exceptionEn":"Use lo/gli before special consonant clusters; l’ before a vowel.","mistake":{"wrong":"il studente","right":"lo studente"},"rememberIt":"Prima ascolta il suono, poi scegli l’articolo."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('grammar_rule:agreement', 'grammar_rule', NULL, 1403, '{"id":"agreement","titleIt":"Concordanza","titleEn":"Agreement","ruleIt":"L’aggettivo concorda con il nome in genere e numero.","ruleEn":"The adjective agrees with the noun in gender and number.","examples":[{"it":"due ragazze italiane","en":"two Italian girls"}],"exceptionIt":"Gli aggettivi in -e hanno il plurale in -i.","exceptionEn":"Adjectives ending in -e form the plural in -i.","mistake":{"wrong":"due case grande","right":"due case grandi"},"rememberIt":"Controlla l’ultima lettera di nome e aggettivo."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('grammar_rule:plurals', 'grammar_rule', NULL, 1404, '{"id":"plurals","titleIt":"Plurali essenziali","titleEn":"Essential plurals","ruleIt":"Di solito -o→-i, -a→-e e -e→-i.","ruleEn":"Usually -o→-i, -a→-e and -e→-i.","examples":[{"it":"il libro → i libri","en":"the book → the books"}],"exceptionIt":"Parole straniere e accentate spesso non cambiano: i bar, le città.","exceptionEn":"Foreign and stressed-final words are often invariable.","mistake":{"wrong":"le cittàs","right":"le città"},"rememberIt":"Impara nome, articolo e plurale insieme."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('grammar_rule:present', 'grammar_rule', NULL, 1405, '{"id":"present","titleIt":"Presente regolare","titleEn":"Regular present","ruleIt":"Tolgo -are, -ere o -ire e aggiungo la desinenza del soggetto.","ruleEn":"Remove -are, -ere or -ire and add the subject ending.","examples":[{"it":"Parliamo italiano ogni giorno.","en":"We speak Italian every day."}],"exceptionIt":"Alcuni -ire aggiungono -isc-: preferisco.","exceptionEn":"Some -ire verbs add -isc-.","mistake":{"wrong":"Io lavorare a Londra.","right":"Io lavoro a Londra."},"rememberIt":"Segna sempre la famiglia del verbo."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('grammar_rule:irregular', 'grammar_rule', NULL, 1406, '{"id":"irregular","titleIt":"Verbi irregolari frequenti","titleEn":"Frequent irregular verbs","ruleIt":"Essere, avere, fare, andare, stare, venire e uscire si imparano come blocchi.","ruleEn":"Learn common irregular verbs as complete patterns.","examples":[{"it":"Vado al lavoro e faccio sport.","en":"I go to work and do sport."}],"exceptionIt":"Non applicare automaticamente le forme regolari.","exceptionEn":"Do not automatically apply regular endings.","mistake":{"wrong":"Ando al cinema.","right":"Vado al cinema."},"rememberIt":"Crea una frase personale per ogni forma difficile."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('grammar_rule:questions', 'grammar_rule', NULL, 1407, '{"id":"questions","titleIt":"Domande e registro","titleEn":"Questions and register","ruleIt":"Uso chi, cosa, dove, quando, perché, come, quale e quanto per chiedere dettagli.","ruleEn":"Use question words to request specific details.","examples":[{"it":"Dove abita, Signora?","en":"Where do you live, madam?"}],"exceptionIt":"Con Lei uso la terza persona: Come si chiama?","exceptionEn":"Formal Lei takes third-person singular.","mistake":{"wrong":"Come ti chiama?","right":"Come si chiama?"},"rememberIt":"Abbina ogni domanda all’informazione cercata."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('grammar_rule:ordering', 'grammar_rule', NULL, 1408, '{"id":"ordering","titleIt":"Ordinare con cortesia","titleEn":"Ordering politely","ruleIt":"Per ordinare uso vorrei, prendo, per me e posso avere.","ruleEn":"Order with vorrei, prendo, per me and posso avere.","examples":[{"it":"Vorrei un caffè, per favore.","en":"I would like a coffee, please."}],"exceptionIt":"Vorrei è più cortese di voglio.","exceptionEn":"Vorrei is more polite than voglio.","mistake":{"wrong":"Voglio un’acqua!","right":"Vorrei un’acqua, per favore."},"rememberIt":"Aggiungi per favore e chiudi con grazie."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('grammar_rule:buono-bene', 'grammar_rule', NULL, 1409, '{"id":"buono-bene","titleIt":"Buono o bene?","titleEn":"Buono or bene?","ruleIt":"Buono descrive un nome; bene descrive un’azione.","ruleEn":"Buono describes a noun; bene describes an action.","examples":[{"it":"La pizza è buona; cucini bene.","en":"The pizza is good; you cook well."}],"exceptionIt":"Buono cambia forma; bene no.","exceptionEn":"Buono changes form; bene does not.","mistake":{"wrong":"La pasta è bene.","right":"La pasta è buona."},"rememberIt":"Chiediti: cosa oppure come?"}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('grammar_rule:frequency', 'grammar_rule', NULL, 1410, '{"id":"frequency","titleIt":"Frequenza","titleEn":"Frequency","ruleIt":"Uso sempre, spesso, qualche volta, raramente e mai vicino al verbo.","ruleEn":"Use frequency adverbs close to the verb.","examples":[{"it":"Non bevo mai il caffè.","en":"I never drink coffee."}],"exceptionIt":"Con mai normalmente serve anche non.","exceptionEn":"Mai normally also needs non.","mistake":{"wrong":"Bevo mai il caffè.","right":"Non bevo mai il caffè."},"rememberIt":"Ordina gli avverbi da sempre a mai."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('grammar_rule:piacere', 'grammar_rule', NULL, 1411, '{"id":"piacere","titleIt":"Piace o piacciono?","titleEn":"Piace or piacciono?","ruleIt":"La cosa gradita controlla il verbo: piace con singolare/infinito, piacciono con plurale.","ruleEn":"The liked thing controls the verb.","examples":[{"it":"Mi piace ballare; mi piacciono i musei.","en":"I like dancing; I like museums."}],"exceptionIt":"La persona è mi, ti, gli, le, ci, vi o gli.","exceptionEn":"Represent the person with an indirect pronoun.","mistake":{"wrong":"Mi piace le città.","right":"Mi piacciono le città."},"rememberIt":"Guarda la cosa dopo il verbo."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('grammar_rule:time', 'grammar_rule', NULL, 1412, '{"id":"time","titleIt":"Dire l’ora","titleEn":"Telling the time","ruleIt":"Dico è l’una ma sono le due, le tre e così via.","ruleEn":"Say è l’una but sono le due, le tre, and so on.","examples":[{"it":"Sono le otto e un quarto.","en":"It is quarter past eight."}],"exceptionIt":"Per orari: all’una, alle otto.","exceptionEn":"For scheduled times: all’una, alle otto.","mistake":{"wrong":"È le nove.","right":"Sono le nove."},"rememberIt":"Distingui Che ore sono? da A che ora...?"}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('grammar_rule:prepositions', 'grammar_rule', NULL, 1413, '{"id":"prepositions","titleIt":"Preposizioni semplici","titleEn":"Simple prepositions","ruleIt":"Di, a, da, in, con, su, per e tra/fra esprimono relazioni diverse.","ruleEn":"Simple prepositions express different relationships.","examples":[{"it":"Vado a Roma ma vivo in Italia.","en":"I go to Rome but live in Italy."}],"exceptionIt":"Con città uso spesso a; con paesi uso spesso in.","exceptionEn":"Often use a with cities and in with countries.","mistake":{"wrong":"Vivo a Italia.","right":"Vivo in Italia."},"rememberIt":"Impara la preposizione dentro una frase."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('grammar_rule:articulated-preps', 'grammar_rule', NULL, 1414, '{"id":"articulated-preps","titleIt":"Preposizioni articolate","titleEn":"Articulated prepositions","ruleIt":"Di, a, da, in e su si fondono con l’articolo.","ruleEn":"Di, a, da, in and su combine with the article.","examples":[{"it":"Andiamo al museo; la chiave è nella borsa.","en":"We go to the museum; the key is in the bag."}],"exceptionIt":"Trova prima l’articolo del nome.","exceptionEn":"Find the noun’s article first.","mistake":{"wrong":"Vado al stadio.","right":"Vado allo stadio."},"rememberIt":"Scomponi: a + lo = allo; in + la = nella."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('grammar_rule:ce-ci-sono', 'grammar_rule', NULL, 1415, '{"id":"ce-ci-sono","titleIt":"C’è e ci sono","titleEn":"C’è and ci sono","ruleIt":"Uso c’è per una cosa e ci sono per più cose.","ruleEn":"Use c’è for one thing and ci sono for more than one.","examples":[{"it":"C’è un ascensore; ci sono due camere.","en":"There is a lift; there are two rooms."}],"exceptionIt":"Nelle domande mantengo la stessa forma.","exceptionEn":"Questions retain the same form.","mistake":{"wrong":"C’è tre finestre.","right":"Ci sono tre finestre."},"rememberIt":"Conta il nome prima di scegliere."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('grammar_rule:possessives', 'grammar_rule', NULL, 1416, '{"id":"possessives","titleIt":"Possessivi","titleEn":"Possessives","ruleIt":"Il possessivo concorda con la cosa posseduta, non con il proprietario.","ruleEn":"The possessive agrees with the possessed thing.","examples":[{"it":"Marco e la sua casa; Anna e i suoi amici.","en":"Marco and his house; Anna and her friends."}],"exceptionIt":"Di solito c’è l’articolo; spesso manca con un parente singolare non modificato.","exceptionEn":"The article is often omitted with an unmodified singular family member.","mistake":{"wrong":"la mia madre","right":"mia madre"},"rememberIt":"Chiediti quale nome è posseduto."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('grammar_rule:reflexives', 'grammar_rule', NULL, 1417, '{"id":"reflexives","titleIt":"Verbi riflessivi","titleEn":"Reflexive verbs","ruleIt":"Il pronome cambia con il soggetto: mi, ti, si, ci, vi, si.","ruleEn":"The reflexive pronoun changes with the subject.","examples":[{"it":"Mi sveglio alle sette.","en":"I wake up at seven."}],"exceptionIt":"Con un modale: posso alzarmi oppure mi posso alzare.","exceptionEn":"With a modal, attach or place the pronoun before it.","mistake":{"wrong":"Chiamo Samuel.","right":"Mi chiamo Samuel."},"rememberIt":"Scrivi il pronome prima di coniugare."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('grammar_rule:modals', 'grammar_rule', NULL, 1418, '{"id":"modals","titleIt":"Potere, dovere e volere","titleEn":"Can, must and want","ruleIt":"Coniugo il modale e lascio il secondo verbo all’infinito.","ruleEn":"Conjugate the modal and keep the second verb infinitive.","examples":[{"it":"Posso pagare con la carta?","en":"Can I pay by card?"}],"exceptionIt":"Non coniugare entrambi i verbi.","exceptionEn":"Do not conjugate both verbs.","mistake":{"wrong":"Voglio prenoto.","right":"Voglio prenotare."},"rememberIt":"Formula: modale coniugato + infinito."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('grammar_rule:sapere-conoscere', 'grammar_rule', NULL, 1419, '{"id":"sapere-conoscere","titleIt":"Sapere o conoscere?","titleEn":"Sapere or conoscere?","ruleIt":"Sapere riguarda fatti/capacità; conoscere persone, luoghi e familiarità.","ruleEn":"Sapere concerns facts/know-how; conoscere familiarity.","examples":[{"it":"So nuotare; conosco bene Roma.","en":"I can swim; I know Rome well."}],"exceptionIt":"Per una capacità uso sapere + infinito.","exceptionEn":"Use sapere + infinitive for an ability.","mistake":{"wrong":"So Roma.","right":"Conosco Roma."},"rememberIt":"Fatto o capacità = sapere; persona o luogo = conoscere."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('grammar_rule:partitive', 'grammar_rule', NULL, 1420, '{"id":"partitive","titleIt":"Quantità e partitivo","titleEn":"Quantities and partitives","ruleIt":"Del, dello, della, dei, degli e delle indicano quantità non precise.","ruleEn":"Partitives express unspecified quantities.","examples":[{"it":"Vorrei del pane e delle mele.","en":"I would like some bread and apples."}],"exceptionIt":"Dopo una misura precisa uso di.","exceptionEn":"Use di after an exact measure.","mistake":{"wrong":"un chilo della pasta","right":"un chilo di pasta"},"rememberIt":"Decidi: quantità vaga o misura precisa?"}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('grammar_rule:past', 'grammar_rule', NULL, 1421, '{"id":"past","titleIt":"Passato prossimo","titleEn":"Passato prossimo","ruleIt":"Uso il presente di avere o essere più il participio passato.","ruleEn":"Use present avere/essere plus a past participle.","examples":[{"it":"Ho visitato Firenze; siamo arrivati tardi.","en":"I visited Florence; we arrived late."}],"exceptionIt":"Con essere il participio concorda; i riflessivi usano essere.","exceptionEn":"With essere the participle agrees; reflexives use essere.","mistake":{"wrong":"Maria è andato.","right":"Maria è andata."},"rememberIt":"Impara participio e ausiliare insieme."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('grammar_rule:direct-pronouns', 'grammar_rule', NULL, 1422, '{"id":"direct-pronouns","titleIt":"Pronomi diretti","titleEn":"Direct object pronouns","ruleIt":"Lo, la, li e le sostituiscono un oggetto noto e precedono il verbo.","ruleEn":"Direct object pronouns replace a known object and precede the verb.","examples":[{"it":"Compro il pane → Lo compro.","en":"I buy the bread → I buy it."}],"exceptionIt":"Davanti a vocale lo/la possono diventare l’.","exceptionEn":"Before a vowel lo/la may become l’.","mistake":{"wrong":"Vedo la ogni giorno.","right":"La vedo ogni giorno."},"rememberIt":"Trova genere e numero dell’oggetto."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('grammar_rule:colours', 'grammar_rule', NULL, 1423, '{"id":"colours","titleIt":"Colori e vestiti","titleEn":"Colours and clothes","ruleIt":"I colori aggettivali concordano; alcuni colori restano invariabili.","ruleEn":"Adjectival colours agree; some colours stay invariable.","examples":[{"it":"una gonna rossa; due maglie blu","en":"a red skirt; two blue tops"}],"exceptionIt":"Blu, rosa, viola e beige sono normalmente invariabili.","exceptionEn":"Blu, rosa, viola and beige are normally invariable.","mistake":{"wrong":"due pantaloni blui","right":"due pantaloni blu"},"rememberIt":"Descrivi con articolo + nome + colore."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('grammar_rule:invitations', 'grammar_rule', NULL, 1424, '{"id":"invitations","titleIt":"Proposte e inviti","titleEn":"Suggestions and invitations","ruleIt":"Uso vuoi...?, ti va di...?, perché non...? e possiamo... per proporre.","ruleEn":"Use common invitation frames to suggest plans.","examples":[{"it":"Ti va di andare al cinema?","en":"Do you fancy going to the cinema?"}],"exceptionIt":"Dopo di uso l’infinito.","exceptionEn":"Use an infinitive after di.","mistake":{"wrong":"Ti va di ceni fuori?","right":"Ti va di cenare fuori?"},"rememberIt":"Prepara un sì e un no cortese."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('grammar_rule:forms', 'grammar_rule', NULL, 1425, '{"id":"forms","titleIt":"Moduli e dati personali","titleEn":"Forms and personal details","ruleIt":"Riconosco cognome, nome, nascita, nazionalità, indirizzo e firma.","ruleEn":"Recognise standard fields for personal details.","examples":[{"it":"Luogo di nascita: Londra","en":"Place of birth: London"}],"exceptionIt":"Nei campi brevi non servono frasi complete.","exceptionEn":"Short form fields need not be full sentences.","mistake":{"wrong":"Sono nato il data 12/05.","right":"Data di nascita: 12/05."},"rememberIt":"Controlla due volte numeri e grafia."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('verb:essere', 'verb', NULL, 1450, '{"id":"essere","infinitive":"essere","english":"to be","forms":["sono","sei","è","siamo","siete","sono"]}');
